use Doctrine\ORM\Query\AST\Join;

/**
 * AgentRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class DeleguationRepository extends \Doctrine\ORM\EntityRepository {

    public function menuDeleguation($id) {
        $qb = $this->createQueryBuilder('d')
                ->join('d.fonctionalite', 'f')
                ->Where('d.agent = :agent or d.responsable = :agent')
                ->setParameter('agent', $id)
                ->orderBy('d.fonctionalite');

        return $qb->getQuery()->getResult();
    }

    public function menuDeleguationSpec($id, $fonctionaliteid) {
        $qb = $this->createQueryBuilder('d')
                ->Where('d.agent = :agent or d.responsable = :agent')
                ->andWhere('d.fonctionalite = :fonctionalite')
                ->setParameter('agent', $id)
                ->setParameter('fonctionalite', $fonctionaliteid);

        return $qb->getQuery()->getResult();
    }

    /*
