    public function checkRoute($id, $route, $param = null) {
        $qb = $this->createQueryBuilder('d')
                ->Join('d.rubriques', 'r')
                ->Where('d.agent = :agent or d.responsable = :agent')
                ->andWhere('r.route = :route');
        if ($param) {
            $qb->andWhere('r.param = :param')
                    ->setParameter('param', $param);
        }
        $qb->setParameter('agent', $id)
                ->setParameter('route', $route);

        return $qb->getQuery()->getResult();
    }

}
